package com.musicvolumeadjuster;

/**
 * The profiles another profile can be copied into: the three editable user slots. Suggested
 * Settings is deliberately absent, since it's read-only and can only be copied from.
 */
public enum CopyTarget
{
	USER_1("User Settings 1", Profile.USER_1),
	USER_2("User Settings 2", Profile.USER_2),
	USER_3("User Settings 3", Profile.USER_3);

	private final String label;
	private final Profile profile;

	CopyTarget(String label, Profile profile)
	{
		this.label = label;
		this.profile = profile;
	}

	Profile toProfile()
	{
		return profile;
	}

	/** RuneLite's config dropdown displays an enum's toString(). */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.musicvolumeadjuster;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Shown under this plugin's cog in the RuneLite plugin list. Per-track volumes themselves are
 * edited in the sidebar panel, not here — this only holds things that make sense as plugin-wide
 * settings: which profile is active, a reset action for the active one, and the tools for copying
 * volumes between profiles. The action items are checkboxes that act as momentary buttons: they
 * show a confirmation (their warning), run once when confirmed, then flip themselves back off.
 */
@ConfigGroup(TrackVolumes.CONFIG_GROUP)
public interface MusicVolumeAdjusterConfig extends Config
{
	@ConfigItem(
		keyName = "profile",
		name = "Settings profile",
		description = "Switches between the built-in read-only Suggested Settings and three separate editable "
				+ "sets of song volume adjustments (User Settings 1-3).",
		position = 0
	)
	default Profile profile()
	{
		return Profile.USER_1;
	}

	@ConfigItem(
		keyName = "resetToDefault",
		name = "Reset current profile",
		description = "Clears every song volume adjustment in the current profile back to 1.00. "
			+ "Suggested Settings is read-only and is never changed.",
		warning = "This clears every song volume adjustment in the CURRENT profile back to 1.00. "
			+ "This can't be undone. (Suggested Settings is read-only and is not affected.) Continue?",
		position = 1
	)
	default boolean resetToDefault()
	{
		return false;
	}

	@ConfigItem(
		keyName = "importSuggested",
		name = "Import suggested volumes",
		description = "Replaces every song volume adjustment in the current profile with the Suggested Settings. "
			+ "Does nothing while Suggested Settings itself is the current profile.",
		warning = "This REPLACES every song volume adjustment in the CURRENT profile with the Suggested Settings. "
			+ "This can't be undone. Continue?",
		position = 2
	)
	default boolean importSuggested()
	{
		return false;
	}

	@ConfigItem(
		keyName = "copyTarget",
		name = "Copy current profile to",
		description = "The profile that \"Copy now\" will overwrite with a copy of the current profile.",
		position = 3
	)
	default CopyTarget copyTarget()
	{
		return CopyTarget.USER_2;
	}

	@ConfigItem(
		keyName = "copyNow",
		name = "Copy now",
		description = "Replaces every song volume adjustment in the profile chosen above with a copy of the "
			+ "current profile, so the copy can be adjusted without touching the original.",
		warning = "This REPLACES every song volume adjustment in the profile chosen under \"Copy current profile to\" "
			+ "with a copy of the CURRENT profile. This can't be undone. Continue?",
		position = 4
	)
	default boolean copyNow()
	{
		return false;
	}
}

package com.musicvolumeadjuster;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;
import java.awt.Rectangle;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel listing every track in the game, alphabetically, each with a multiplier that can
 * be nudged with +/- buttons (0.01 per click) or typed directly. A search box filters the list.
 *
 * A "Now Playing" row is pinned above the search box and always tracks whatever's currently
 * playing (set by the plugin via {@link #setNowPlayingTrack}). It shares the same underlying
 * multiplier as the matching row further down the list: changing either one updates the other,
 * and both apply live if that track is playing right now. The list itself is never reordered.
 *
 * While the read-only Suggested profile is active, every row is disabled. Switching, copying and
 * resetting profiles all happen from the plugin's settings (gear icon); this panel just shows the
 * active profile and the outcome of the last copy/import via {@link #showStatus}.
 */
class MusicVolumeAdjusterPanel extends PluginPanel
{
	private static final double STEP = 0.01;

	private final TrackVolumes trackVolumes;
	private final MusicVolumeAdjusterPlugin plugin;
	private final RowContainer rowContainer = new RowContainer();
	private final List<TrackRow> rows = new ArrayList<>();
	private final Map<String, TrackRow> rowsByNormalizedName = new HashMap<>();
	private final NowPlayingRow nowPlayingRow;
	private final JLabel profileLabel;
	private final JLabel statusLabel;
	private final JTextField search;

	MusicVolumeAdjusterPanel(TrackVolumes trackVolumes, MusicVolumeAdjusterPlugin plugin)
	{
		super(false);
		this.trackVolumes = trackVolumes;
		this.plugin = plugin;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Music Volume Adjuster");
		title.setForeground(Color.WHITE);
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setBorder(new EmptyBorder(0, 0, 2, 0));

		profileLabel = new JLabel();
		profileLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		profileLabel.setFont(FontManager.getRunescapeSmallFont());
		profileLabel.setToolTipText("Switch, copy or reset profiles from this plugin's gear icon in the plugin list");
		profileLabel.setBorder(new EmptyBorder(0, 0, 2, 0));

		statusLabel = new JLabel(" ");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setBorder(new EmptyBorder(0, 0, 8, 0));

		JLabel nowPlayingHeader = new JLabel("NOW PLAYING");
		nowPlayingHeader.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		nowPlayingHeader.setFont(FontManager.getRunescapeSmallFont());
		nowPlayingHeader.setBorder(new EmptyBorder(0, 2, 2, 0));

		nowPlayingRow = new NowPlayingRow();

		JPanel nowPlayingSection = new JPanel(new BorderLayout());
		nowPlayingSection.setOpaque(false);
		nowPlayingSection.setBorder(new EmptyBorder(0, 0, 10, 0));
		nowPlayingSection.add(nowPlayingHeader, BorderLayout.NORTH);
		nowPlayingSection.add(nowPlayingRow.component, BorderLayout.CENTER);

		search = new JTextField();
		search.setToolTipText("Search tracks");
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				filter(search.getText());
			}
		});

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.setBackground(ColorScheme.DARK_GRAY_COLOR);
		top.add(title);
		top.add(profileLabel);
		top.add(statusLabel);
		top.add(nowPlayingSection);
		top.add(search);

		rowContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		for (String name : trackVolumes.getAllTrackNames())
		{
			TrackRow row = new TrackRow(name);
			rows.add(row);
			rowsByNormalizedName.put(TrackVolumes.normalize(name), row);
			rowContainer.add(row.component);
		}

		JScrollPane scroll = new JScrollPane(rowContainer);
		scroll.setBorder(null);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(top, BorderLayout.NORTH);
		add(scroll, BorderLayout.CENTER);

		updateProfileControls();
	}

	/**
	 * Called by the plugin whenever the playing track changes. Safe to call from any thread; an
	 * empty or null name clears the row (nothing playing / logged out).
	 */
	void setNowPlayingTrack(String displayName)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> setNowPlayingTrack(displayName));
			return;
		}
		nowPlayingRow.bind(displayName == null ? "" : displayName);
	}

	/**
	 * Adds a row for a song that wasn't in the track list (the plugin found it playing), in its
	 * alphabetical place. Safe to call from any thread; does nothing if the row already exists.
	 */
	void addTrack(String name)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> addTrack(name));
			return;
		}

		String norm = TrackVolumes.normalize(name);
		if (rowsByNormalizedName.containsKey(norm))
		{
			return;
		}

		TrackRow row = new TrackRow(name);
		row.setEditable(!trackVolumes.getCurrentProfile().isReadOnly());

		int index = 0;
		while (index < rows.size() && TrackVolumes.TRACK_ORDER.compare(rows.get(index).name, name) <= 0)
		{
			index++;
		}
		rows.add(index, row);
		rowsByNormalizedName.put(norm, row);
		rowContainer.add(row.component, index);

		filter(search.getText());
	}

	/**
	 * Called by the plugin after the active profile changes or is reset, so every displayed value
	 * (the full list and the Now Playing row) reflects the new profile's stored multipliers.
	 */
	void refreshAllMultipliers()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(this::refreshAllMultipliers);
			return;
		}

		for (TrackRow row : rows)
		{
			row.refreshSilently(trackVolumes.getMultiplier(TrackVolumes.normalize(row.name)));
		}
		if (nowPlayingRow.boundNormalizedName != null)
		{
			nowPlayingRow.refreshSilently(trackVolumes.getMultiplier(nowPlayingRow.boundNormalizedName));
		}
		updateProfileControls();
	}

	/**
	 * Brings everything that depends on the active profile up to date: the label, and whether the
	 * rows are editable (not for the read-only Suggested Settings). Must run on the EDT.
	 */
	private void updateProfileControls()
	{
		Profile current = trackVolumes.getCurrentProfile();
		boolean readOnly = current.isReadOnly();

		profileLabel.setText("Profile: " + current + (readOnly ? " (read-only)" : ""));

		for (TrackRow row : rows)
		{
			row.setEditable(!readOnly);
		}
		nowPlayingRow.setProfileEditable(!readOnly);
	}

	/** Shows a short result message (e.g. "Copied to User Settings 2") under the profile name. */
	void showStatus(String text)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			SwingUtilities.invokeLater(() -> showStatus(text));
			return;
		}
		statusLabel.setText(text);
	}

	private void filter(String query)
	{
		String q = query.trim().toLowerCase();
		for (TrackRow row : rows)
		{
			row.component.setVisible(q.isEmpty() || row.lowerName.contains(q));
		}
		rowContainer.revalidate();
		rowContainer.repaint();
	}

	private static double parseOrFallback(String text, double fallback)
	{
		try
		{
			return Double.parseDouble(text.trim());
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	private static String format(double value)
	{
		return String.format("%.2f", value);
	}

	private static JButton smallButton(String text)
	{
		JButton b = new JButton(text);
		b.setMargin(new Insets(0, 4, 0, 4));
		b.setFocusable(false);
		return b;
	}

	/**
	 * Holds the track rows and forces its width to always match the viewport (the sidebar's
	 * actual visible width), regardless of how wide a row's content wants to be. Without this,
	 * a long track name can make the whole list wider than the sidebar, pushing the +/- controls
	 * off the visible edge instead of just letting the name clip.
	 */
	private static class RowContainer extends JPanel implements Scrollable
	{
		RowContainer()
		{
			setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/** One row in the full alphabetical list, permanently bound to a single track. */
	private class TrackRow
	{
		final String name;
		final String lowerName;
		final JPanel component;
		final JTextField field;
		final JButton minus;
		final JButton plus;

		TrackRow(String name)
		{
			this.name = name;
			this.lowerName = name.toLowerCase();

			JLabel label = new JLabel(name);
			label.setForeground(Color.LIGHT_GRAY);
			label.setFont(FontManager.getRunescapeSmallFont());
			label.setToolTipText(name); // full name on hover, in case it's clipped for width

			double initial = trackVolumes.getMultiplier(TrackVolumes.normalize(name));
			field = new JTextField(format(initial));
			field.setHorizontalAlignment(SwingConstants.CENTER);
			field.setColumns(4);

			minus = smallButton("\u2212");
			plus = smallButton("+");
			minus.addActionListener(e -> adjust(-STEP));
			plus.addActionListener(e -> adjust(STEP));

			// Commit on Enter and when the field loses focus, so keyboard input works too
			field.addActionListener(e -> commitFromField());
			field.addFocusListener(new FocusAdapter()
			{
				@Override
				public void focusLost(FocusEvent e)
				{
					commitFromField();
				}
			});

			JPanel controls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
			controls.setOpaque(false);
			controls.add(minus);
			controls.add(field);
			controls.add(plus);

			component = new JPanel(new BorderLayout());
			component.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			component.setBorder(new EmptyBorder(4, 6, 4, 6));
			component.add(label, BorderLayout.CENTER);
			component.add(controls, BorderLayout.EAST);
			component.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
			component.setAlignmentX(0f);
		}

		/** Updates the displayed value only, without writing to storage or re-notifying anyone. */
		void refreshSilently(double value)
		{
			field.setText(format(value));
		}

		void setEditable(boolean editable)
		{
			field.setEnabled(editable);
			minus.setEnabled(editable);
			plus.setEnabled(editable);
		}

		private void adjust(double delta)
		{
			set(parseOrFallback(field.getText(), currentValue()) + delta);
		}

		private void commitFromField()
		{
			set(parseOrFallback(field.getText(), currentValue()));
		}

		private double currentValue()
		{
			return trackVolumes.getMultiplier(TrackVolumes.normalize(name));
		}

		private void set(double value)
		{
			if (trackVolumes.getCurrentProfile().isReadOnly())
			{
				return;
			}
			value = TrackVolumes.clamp(value);
			field.setText(format(value));
			trackVolumes.setMultiplier(name, value);
			plugin.onMultiplierChanged(name);

			// Keep the pinned Now Playing row in sync if it's showing this same track
			if (TrackVolumes.normalize(name).equals(nowPlayingRow.boundNormalizedName))
			{
				nowPlayingRow.refreshSilently(value);
			}
		}
	}

	/**
	 * The pinned row above the search box. Its bound track changes as songs change; editing it
	 * writes through to the same storage as the matching row in the list below, and keeps that
	 * row visually in sync.
	 */
	private class NowPlayingRow
	{
		String boundDisplayName = "";
		String boundNormalizedName = null;
		boolean profileEditable = true;

		final JLabel nameLabel;
		final JTextField field;
		final JButton minus;
		final JButton plus;
		final JPanel component;

		NowPlayingRow()
		{
			nameLabel = new JLabel("Nothing playing");
			nameLabel.setForeground(Color.WHITE);
			nameLabel.setFont(FontManager.getRunescapeSmallFont());

			field = new JTextField(format(1.0));
			field.setHorizontalAlignment(SwingConstants.CENTER);
			field.setColumns(4);
			field.setEnabled(false);

			minus = smallButton("\u2212");
			plus = smallButton("+");
			minus.setEnabled(false);
			plus.setEnabled(false);
			minus.addActionListener(e -> adjust(-STEP));
			plus.addActionListener(e -> adjust(STEP));

			field.addActionListener(e -> commitFromField());
			field.addFocusListener(new FocusAdapter()
			{
				@Override
				public void focusLost(FocusEvent e)
				{
					commitFromField();
				}
			});

			JPanel controls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
			controls.setOpaque(false);
			controls.add(minus);
			controls.add(field);
			controls.add(plus);

			component = new JPanel(new BorderLayout());
			component.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			component.setBorder(new EmptyBorder(6, 6, 6, 6));
			component.add(nameLabel, BorderLayout.CENTER);
			component.add(controls, BorderLayout.EAST);
		}

		void bind(String displayName)
		{
			boundDisplayName = displayName;
			boolean has = !displayName.isEmpty();
			boundNormalizedName = has ? TrackVolumes.normalize(displayName) : null;

			nameLabel.setText(has ? displayName : "Nothing playing");
			nameLabel.setToolTipText(has ? displayName : null);
			updateEnabled();

			if (has)
			{
				field.setText(format(trackVolumes.getMultiplier(boundNormalizedName)));
			}
		}

		/** Called when the active profile changes between editable and read-only. */
		void setProfileEditable(boolean editable)
		{
			profileEditable = editable;
			updateEnabled();
		}

		private void updateEnabled()
		{
			boolean enabled = boundNormalizedName != null && profileEditable;
			field.setEnabled(enabled);
			minus.setEnabled(enabled);
			plus.setEnabled(enabled);
		}

		void refreshSilently(double value)
		{
			field.setText(format(value));
		}

		private void adjust(double delta)
		{
			set(parseOrFallback(field.getText(), currentValue()) + delta);
		}

		private void commitFromField()
		{
			set(parseOrFallback(field.getText(), currentValue()));
		}

		private double currentValue()
		{
			return boundNormalizedName == null ? 1.0 : trackVolumes.getMultiplier(boundNormalizedName);
		}

		private void set(double value)
		{
			if (boundNormalizedName == null || !profileEditable)
			{
				return;
			}
			value = TrackVolumes.clamp(value);
			field.setText(format(value));
			trackVolumes.setMultiplier(boundDisplayName, value);
			plugin.onMultiplierChanged(boundDisplayName);

			TrackRow match = rowsByNormalizedName.get(boundNormalizedName);
			if (match != null)
			{
				match.refreshSilently(value);
			}
		}
	}
}

package com.musicvolumeadjuster;

import java.util.List;
import javax.inject.Inject;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MidiRequest;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Music Volume Adjuster",
	description = "Applies a per-track volume adjustment so loud and quiet songs sound even",
	tags = {"music", "volume", "audio", "equalizer", "adjuster"}
)
public class MusicVolumeAdjusterPlugin extends Plugin
{
	private static final int MAX_VOLUME = 255;

	/** A new song starts at this volume and ramps up to its target. 0 would stop playback. */
	private static final int RAMP_START_VOLUME = 1;
	private static final long RAMP_DURATION_MS = 2000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TrackVolumes trackVolumes;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private MusicVolumeAdjusterConfig config;

	@Provides
	MusicVolumeAdjusterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MusicVolumeAdjusterConfig.class);
	}

	private NavigationButton navButton;
	private MusicVolumeAdjusterPanel panel;

	private String currentTrack = "";

	/** When the current volume ramp began, or -1 if no ramp is running. */
	private long rampStartMs = -1;

	/** The volume the running ramp is heading for. Only meaningful while rampStartMs >= 0. */
	private int rampTarget = -1;

	/**
	 * The player's own volume slider value. Note: client.getMusicVolume() always returns this
	 * value and never reflects what setMusicVolume() last set, so it's a reliable way to detect
	 * a genuine slider move, but useless for detecting whether our own adjustment is still live.
	 */
	private int baseVolume = -1;

	/** The last value we passed to setMusicVolume (either baseVolume or an adjusted value). */
	private int appliedVolume = -1;

	/**
	 * True while we own the live volume and keep re-asserting appliedVolume: either an adjusted
	 * volume (different from baseVolume) is in effect, or a ramp is running.
	 */
	private boolean adjustmentActive = false;

	/**
	 * True while a jingle (e.g. quest complete, diary complete, slayer task complete) is one of
	 * the active midi requests. Jingles share the music volume channel but aren't reflected in
	 * the Music tab's "now playing" text, so without this they'd inherit whatever multiplier the
	 * background track has, which can make them uncomfortably loud on a boosted track.
	 */
	private boolean jinglePlaying = false;

	@Override
	protected void startUp()
	{
		panel = new MusicVolumeAdjusterPanel(trackVolumes, this);
		navButton = NavigationButton.builder()
			.tooltip("Music Volume Adjuster")
			.icon(ImageUtil.loadImageResource(getClass(), "/icon.png"))
			.priority(5)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		resetState();
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}

		clientThread.invoke(() ->
		{
			restoreBaseVolume();
			resetState();
		});

		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Logged out: put the player's own volume back so it isn't saved as the adjusted one
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			restoreBaseVolume();
			resetState();
		}
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		restoreBaseVolume();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TrackVolumes.CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("profile".equals(event.getKey()))
		{
			Profile newProfile;
			try
			{
				newProfile = Profile.valueOf(event.getNewValue());
			}
			catch (Exception e)
			{
				newProfile = Profile.USER_1;
			}
			trackVolumes.setCurrentProfile(newProfile);
			if (panel != null)
			{
				panel.refreshAllMultipliers();
			}
			reapplyCurrentTrackLive();
		}
		else if ("resetToDefault".equals(event.getKey()))
		{
			// The checkbox-as-button pattern: only act on the true edge (the person confirmed
			// the warning dialog), then flip it back off so it reads as a momentary action.
			if (!"true".equals(event.getNewValue()))
			{
				return;
			}

			Profile profile = trackVolumes.getCurrentProfile();
			if (profile.isReadOnly())
			{
				log.debug("Ignoring reset of read-only profile {}", profile);
			}
			else
			{
				trackVolumes.resetProfile(profile);
				log.debug("Reset profile {} to default", profile);

				if (panel != null)
				{
					panel.refreshAllMultipliers();
				}
				reapplyCurrentTrackLive();
			}

			configManager.setConfiguration(TrackVolumes.CONFIG_GROUP, "resetToDefault", "false");
		}
		else if ("importSuggested".equals(event.getKey()))
		{
			if (!"true".equals(event.getNewValue()))
			{
				return;
			}

			importSuggested();
			configManager.setConfiguration(TrackVolumes.CONFIG_GROUP, "importSuggested", "false");
		}
		else if ("copyNow".equals(event.getKey()))
		{
			if (!"true".equals(event.getNewValue()))
			{
				return;
			}

			copyToTarget();
			configManager.setConfiguration(TrackVolumes.CONFIG_GROUP, "copyNow", "false");
		}
	}

	/** Overwrites the active user profile with the Suggested Settings. */
	private void importSuggested()
	{
		Profile target = trackVolumes.getCurrentProfile();
		if (target.isReadOnly())
		{
			showStatus("Switch to a User profile to import into it");
			return;
		}

		if (trackVolumes.copyProfile(Profile.SUGGESTED, target))
		{
			log.debug("Imported suggested volumes into {}", target);
			profileContentsChanged("Imported suggested volumes");
		}
	}

	/** Overwrites the profile chosen in the settings with a copy of the active profile. */
	private void copyToTarget()
	{
		Profile source = trackVolumes.getCurrentProfile();
		Profile target = config.copyTarget().toProfile();
		if (source == target)
		{
			showStatus("Pick a different profile to copy to");
			return;
		}

		if (trackVolumes.copyProfile(source, target))
		{
			log.debug("Copied {} to {}", source, target);
			showStatus("Copied to " + target);
		}
	}

	/** The active profile's volumes were replaced: refresh what's shown and what's playing. */
	private void profileContentsChanged(String status)
	{
		if (panel != null)
		{
			panel.refreshAllMultipliers();
		}
		showStatus(status);
		reapplyCurrentTrackLive();
	}

	private void showStatus(String text)
	{
		if (panel != null)
		{
			panel.showStatus(text);
		}
	}

	/**
	 * Recalculates the live volume for whatever's currently playing, e.g. after a profile switch or
	 * after a profile's contents were replaced by a copy/import. Applied straight away, not ramped.
	 */
	void reapplyCurrentTrackLive()
	{
		clientThread.invoke(() ->
		{
			if (baseVolume < 0 || client.getGameState() != GameState.LOGGED_IN
				|| currentTrack.isEmpty() || jinglePlaying)
			{
				return;
			}
			applyModifier();
		});
	}

	/**
	 * The game silently resets the live volume back to the slider value at times (e.g. switching
	 * inventory tabs), inside a client script, and getMusicVolume() can't tell us when — it always
	 * mirrors the slider anyway. So rather than trying to detect a reset, this just re-asserts the
	 * adjusted volume after every script while one should be active. That's a lot of calls, but
	 * each is a cheap, idempotent int write, and correcting within the same frame the game resets
	 * it is what keeps a tab switch from producing an audible dip. Not logged per-call, since at
	 * this frequency that's log noise rather than useful signal.
	 */
	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (adjustmentActive)
		{
			client.setMusicVolume(appliedVolume);
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		// getMusicVolume() always mirrors the player's own slider, never what we set, so any
		// change here is a genuine slider move (or the first reading after login)
		int reading = client.getMusicVolume();
		if (reading != baseVolume)
		{
			setBase(reading);
		}

		// Duck to the player's own (unboosted/uncut) volume while a jingle is playing, since
		// jingles share the music channel but don't show up in the "now playing" text, so we'd
		// otherwise apply whatever multiplier the background track has to them too.
		boolean jingleNow = isJinglePlaying();
		if (jingleNow != jinglePlaying)
		{
			jinglePlaying = jingleNow;
			if (jinglePlaying)
			{
				log.debug("Jingle started, holding at base {}", baseVolume);
				holdAtBase();
			}
			else
			{
				log.debug("Jingle ended, resuming track adjustment");
				applyModifier();
			}
		}

		// Detect song transitions from the Music tab's "Now playing" text
		Widget trackWidget = client.getWidget(InterfaceID.Music.NOW_PLAYING_TEXT);
		if (trackWidget != null && baseVolume >= 0)
		{
			String rawText = trackWidget.getText();
			String track = TrackVolumes.normalize(rawText);
			if (!track.isEmpty() && !track.equals(currentTrack))
			{
				currentTrack = track;
				log.debug("Track changed: '{}'", track);

				// If a jingle is playing right now, hold at the player's own volume and leave it
				// to the jingle-ended branch above to apply the new song's volume, rather than
				// ramping up underneath the jingle. Otherwise slam to the floor and ramp up.
				if (jinglePlaying)
				{
					holdAtBase();
				}
				else
				{
					startRamp();
				}

				if (panel != null)
				{
					String displayName = TrackVolumes.cleanDisplayName(rawText);

					// A song the track list doesn't have yet (e.g. added to the game since): give
					// it a row of its own. It plays at 1.00 until the person adjusts it.
					if (trackVolumes.addDiscoveredTrack(displayName))
					{
						panel.addTrack(displayName);
					}
					panel.setNowPlayingTrack(displayName);
				}
			}
		}

		// The game silently resets the live volume back to the slider value at times (e.g.
		// switching inventory tabs), and getMusicVolume() can't tell us when that happens, since
		// it always reads the slider anyway. So instead of trying to detect the reset, just keep
		// re-asserting the adjusted volume every tick while one should be active. Cheap (one call
		// per tick, only while a track is actually boosted, cut or ramping) and needs no detection
		// at all. While a ramp is running, the same call also moves the volume one step along it.
		if (rampStartMs >= 0)
		{
			advanceRamp();
		}
		else if (adjustmentActive)
		{
			client.setMusicVolume(appliedVolume);
		}
	}

	/**
	 * Called from the panel (on the EDT) when the player changes a track's multiplier — either
	 * from the full list or from the pinned Now Playing row. If that track is playing right now,
	 * the volume is recalculated from the base volume immediately, instead of waiting for the
	 * next song change.
	 */
	void onMultiplierChanged(String trackDisplayName)
	{
		clientThread.invoke(() ->
		{
			if (baseVolume < 0 || client.getGameState() != GameState.LOGGED_IN || jinglePlaying)
			{
				return;
			}
			String norm = TrackVolumes.normalize(trackDisplayName);
			if (norm.equals(currentTrack))
			{
				applyModifier();
			}
		});
	}

	/** True if any currently active midi request is a jingle (a short sting like quest/diary/slayer-task complete). */
	private boolean isJinglePlaying()
	{
		List<MidiRequest> active = client.getActiveMidiRequests();
		if (active == null)
		{
			return false;
		}
		for (MidiRequest request : active)
		{
			if (request != null && request.isJingle())
			{
				return true;
			}
		}
		return false;
	}

	private void setBase(int volume)
	{
		log.debug("Base volume {} -> {}", baseVolume, volume);
		baseVolume = volume;
		appliedVolume = volume;
		adjustmentActive = false;
		rampStartMs = -1;
	}

	/** The volume the current track should settle at: the player's volume times the track's multiplier. */
	private int computeTarget()
	{
		double multiplier = trackVolumes.getMultiplier(currentTrack);
		int target = (int) Math.round(baseVolume * multiplier);
		target = Math.max(0, Math.min(MAX_VOLUME, target));

		log.debug("'{}': base {} x {} -> {}", currentTrack, baseVolume, multiplier, target);
		return target;
	}

	private void setLive(int volume)
	{
		client.setMusicVolume(volume);
		appliedVolume = volume;
	}

	/** Puts the live volume at the player's own level and stops adjusting until told otherwise. */
	private void holdAtBase()
	{
		rampStartMs = -1;
		adjustmentActive = false;
		if (baseVolume >= 0)
		{
			setLive(baseVolume);
		}
	}

	/**
	 * Starts a new song: slams the volume to the floor, then {@link #advanceRamp} raises it to the
	 * song's target over {@link #RAMP_DURATION_MS}. If the target is already at or below the floor
	 * (e.g. the player has music muted) there's nothing to ramp, so it's set directly instead.
	 */
	private void startRamp()
	{
		if (baseVolume < 0)
		{
			return;
		}

		int target = computeTarget();
		if (target <= RAMP_START_VOLUME)
		{
			rampStartMs = -1;
			setLive(target);
			adjustmentActive = target != baseVolume;
			return;
		}

		rampTarget = target;
		rampStartMs = System.currentTimeMillis();
		adjustmentActive = true;
		setLive(RAMP_START_VOLUME);
	}

	/** Moves the live volume one step along the running ramp, finishing it once the time is up. */
	private void advanceRamp()
	{
		long elapsed = System.currentTimeMillis() - rampStartMs;
		if (elapsed >= RAMP_DURATION_MS)
		{
			rampStartMs = -1;
			setLive(rampTarget);
			adjustmentActive = rampTarget != baseVolume;
			return;
		}

		double progress = elapsed / (double) RAMP_DURATION_MS;
		setLive(RAMP_START_VOLUME + (int) Math.round((rampTarget - RAMP_START_VOLUME) * progress));
	}

	/**
	 * Applies the current track's volume straight away, with no ramp. Used when something changes
	 * mid-song (a multiplier edit, a profile switch, a jingle ending). If a ramp is already running
	 * it just gets a new destination instead, so the volume keeps rising smoothly.
	 */
	private void applyModifier()
	{
		if (baseVolume < 0)
		{
			return;
		}

		int target = computeTarget();
		if (rampStartMs >= 0 && target > RAMP_START_VOLUME)
		{
			rampTarget = target;
			return;
		}

		rampStartMs = -1;
		setLive(target);
		adjustmentActive = target != baseVolume;
	}

	/** Puts the live volume back to the player's own level if we had adjusted it. */
	private void restoreBaseVolume()
	{
		if (baseVolume >= 0 && adjustmentActive)
		{
			client.setMusicVolume(baseVolume);
			appliedVolume = baseVolume;
		}
		adjustmentActive = false;
		rampStartMs = -1;
	}

	private void resetState()
	{
		boolean hadTrack = !currentTrack.isEmpty();
		currentTrack = "";
		rampStartMs = -1;
		rampTarget = -1;
		baseVolume = -1;
		appliedVolume = -1;
		adjustmentActive = false;
		jinglePlaying = false;

		if (hadTrack && panel != null)
		{
			panel.setNowPlayingTrack("");
		}
	}
}

package com.musicvolumeadjuster;

/**
 * The four sets of track volume adjustments a person can switch between. SUGGESTED ships with a
 * curated set of volumes (bundled in suggested.json) and is read-only, so it always stays as
 * shipped; the three USER slots are freely editable and can be filled from it with a copy.
 */
public enum Profile
{
	SUGGESTED("Suggested Settings"),
	USER_1("User Settings 1"),
	USER_2("User Settings 2"),
	USER_3("User Settings 3");

	private final String label;

	Profile(String label)
	{
		this.label = label;
	}

	/** True for the built-in profile that can't be edited, only copied from. */
	public boolean isReadOnly()
	{
		return this == SUGGESTED;
	}

	/** RuneLite's config dropdown displays an enum's toString(). */
	@Override
	public String toString()
	{
		return label;
	}
}

package com.musicvolumeadjuster;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * Holds the per-track volume multiplier table, one set per {@link Profile}.
 *
 * The full track list comes from the bundled tracks.txt resource (every song in the game).
 * Every track defaults to a multiplier of 1.0 (unchanged); only tracks the person has actually
 * adjusted are stored, as a small JSON map per profile, via ConfigManager.
 *
 * The read-only {@link Profile#SUGGESTED} profile is the exception: its values come from the
 * bundled suggested.json resource and are never written to the config.
 */
@Slf4j
@Singleton
class TrackVolumes
{
	static final String CONFIG_GROUP = "musicvolumeadjuster";

	/** Config group used before the plugin was renamed; read once to migrate saved settings. */
	private static final String LEGACY_CONFIG_GROUP = "musicvolumeequalizer";
	private static final String PROFILE_KEY = "profile";
	private static final String RESET_KEY = "resetToDefault";
	private static final String DATA_KEY_PREFIX = "trackMultipliers_"; // + Profile.name()
	private static final String TRACK_LIST_RESOURCE = "/tracks.txt";
	private static final String SUGGESTED_RESOURCE = "/suggested.json";
	private static final String DISCOVERED_KEY = "discoveredTracks";

	/** Longest track name accepted as a newly discovered song; anything longer isn't a song title. */
	private static final int MAX_DISCOVERED_NAME_LENGTH = 64;

	static final double MIN_MULTIPLIER = 0.00;
	static final double MAX_MULTIPLIER = 5.00;

	private final ConfigManager configManager;
	private final Gson gson;

	/**
	 * Every known track, original display casing, sorted alphabetically: the bundled list plus any
	 * songs discovered while playing. Guarded by "this", since discoveries arrive on the client thread.
	 */
	private final List<String> allTrackNames;

	/** Normalized names of everything in allTrackNames, for quick "do we know this song" checks. */
	private final Set<String> knownNormalizedNames = new HashSet<>();

	/** Normalized names from the bundled tracks.txt only, so discovered songs can be told apart. */
	private final Set<String> bundledNormalizedNames = new HashSet<>();

	/** One "normalized track name -> multiplier" map per profile. Only non-1.0 entries are kept. */
	private final Map<Profile, Map<String, Double>> profileOverrides = new EnumMap<>(Profile.class);

	private Profile currentProfile;

	@Inject
	TrackVolumes(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
		this.allTrackNames = loadTrackNames();
		for (String name : allTrackNames)
		{
			knownNormalizedNames.add(normalize(name));
		}
		bundledNormalizedNames.addAll(knownNormalizedNames);

		migrateLegacyConfig();
		loadDiscoveredTracks();

		for (Profile profile : Profile.values())
		{
			profileOverrides.put(profile, profile.isReadOnly() ? loadSuggested() : loadOverrides(profile));
		}

		currentProfile = loadCurrentProfile();
	}

	/**
	 * The config group was renamed along with the plugin. Moves anything saved under the old group
	 * to the new one so nobody's profiles or volumes are lost, then clears the old keys. A value
	 * already present under the new group is never overwritten.
	 */
	private void migrateLegacyConfig()
	{
		List<String> keys = new ArrayList<>();
		keys.add(PROFILE_KEY);
		keys.add(RESET_KEY);
		for (Profile profile : Profile.values())
		{
			keys.add(DATA_KEY_PREFIX + profile.name());
		}

		for (String key : keys)
		{
			String legacy = configManager.getConfiguration(LEGACY_CONFIG_GROUP, key);
			if (legacy == null)
			{
				continue;
			}
			if (!RESET_KEY.equals(key) && configManager.getConfiguration(CONFIG_GROUP, key) == null)
			{
				configManager.setConfiguration(CONFIG_GROUP, key, legacy);
				log.debug("Migrated legacy config key {}", key);
			}
			configManager.unsetConfiguration(LEGACY_CONFIG_GROUP, key);
		}
	}

	/** Loads the bundled Suggested Settings table. Entries at 1.0 are dropped, like stored ones. */
	private Map<String, Double> loadSuggested()
	{
		Map<String, Double> map = new HashMap<>();
		try (InputStream is = TrackVolumes.class.getResourceAsStream(SUGGESTED_RESOURCE))
		{
			if (is == null)
			{
				log.warn("suggested.json resource not found");
				return map;
			}
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8)))
			{
				Type type = new TypeToken<Map<String, Double>>()
				{
				}.getType();
				Map<String, Double> bundled = gson.fromJson(reader, type);
				if (bundled != null)
				{
					for (Map.Entry<String, Double> entry : bundled.entrySet())
					{
						double value = clamp(entry.getValue());
						if (Math.abs(value - 1.0) >= 0.001)
						{
							map.put(normalize(entry.getKey()), value);
						}
					}
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read suggested.json", e);
		}
		return map;
	}

	private List<String> loadTrackNames()
	{
		List<String> names = new ArrayList<>();
		try (InputStream is = TrackVolumes.class.getResourceAsStream(TRACK_LIST_RESOURCE))
		{
			if (is == null)
			{
				log.warn("tracks.txt resource not found");
				return names;
			}
			try (BufferedReader reader = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					line = line.trim();
					if (!line.isEmpty())
					{
						names.add(line);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Failed to read tracks.txt", e);
		}
		names.sort(TRACK_ORDER);
		return names;
	}

	/** Songs found in-game that the bundled list didn't have, saved so they stay listed next launch. */
	private void loadDiscoveredTracks()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, DISCOVERED_KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Type type = new TypeToken<List<String>>()
			{
			}.getType();
			List<String> saved = gson.fromJson(json, type);
			if (saved != null)
			{
				for (String name : saved)
				{
					insertTrack(name);
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to parse saved discovered tracks, ignoring them", e);
		}
	}

	/** Inserts a track at its alphabetical position unless it's already known. */
	private synchronized boolean insertTrack(String displayName)
	{
		if (!knownNormalizedNames.add(normalize(displayName)))
		{
			return false;
		}
		int index = 0;
		while (index < allTrackNames.size() && TRACK_ORDER.compare(allTrackNames.get(index), displayName) <= 0)
		{
			index++;
		}
		allTrackNames.add(index, displayName);
		return true;
	}

	/**
	 * Records a song the game is playing that isn't in the track list yet, so it gets its own row
	 * in the panel. It starts at 1.00 (no override stored), same as any untouched track, until the
	 * person adjusts it.
	 *
	 * @return true if the song was new (so the caller should add a row for it)
	 */
	boolean addDiscoveredTrack(String displayName)
	{
		if (displayName == null)
		{
			return false;
		}
		displayName = displayName.trim();
		if (displayName.isEmpty() || displayName.length() > MAX_DISCOVERED_NAME_LENGTH
			|| !insertTrack(displayName))
		{
			return false;
		}

		log.debug("Discovered new track '{}'", displayName);
		persistDiscovered();
		return true;
	}

	private synchronized void persistDiscovered()
	{
		List<String> discovered = new ArrayList<>();
		for (String name : allTrackNames)
		{
			if (!bundledNormalizedNames.contains(normalize(name)))
			{
				discovered.add(name);
			}
		}
		configManager.setConfiguration(CONFIG_GROUP, DISCOVERED_KEY, gson.toJson(discovered));
	}

	// Same articles the game itself ignores when alphabetizing the music list
	private static final List<String> LEADING_ARTICLES = Arrays.asList("the ", "an ", "a ");

	/** Alphabetical order, ignoring a leading "The"/"A"/"An" like the game's own music list. */
	static final Comparator<String> TRACK_ORDER = Comparator.comparing(TrackVolumes::sortKey);

	private static String sortKey(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		for (String article : LEADING_ARTICLES)
		{
			if (lower.startsWith(article))
			{
				return lower.substring(article.length());
			}
		}
		return lower;
	}

	private Profile loadCurrentProfile()
	{
		String saved = configManager.getConfiguration(CONFIG_GROUP, PROFILE_KEY);
		if (saved != null)
		{
			try
			{
				return Profile.valueOf(saved);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Unknown saved profile '{}', defaulting to USER_1", saved);
			}
		}
		return Profile.USER_1;
	}

	private Map<String, Double> loadOverrides(Profile profile)
	{
		Map<String, Double> map = new HashMap<>();
		String json = configManager.getConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + profile.name());
		if (json == null || json.isEmpty())
		{
			return map;
		}
		try
		{
			Type type = new TypeToken<Map<String, Double>>()
			{
			}.getType();
			Map<String, Double> saved = gson.fromJson(json, type);
			if (saved != null)
			{
				map.putAll(saved);
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to parse saved multipliers for {}, starting fresh", profile, e);
		}
		return map;
	}

	private void persist(Profile profile)
	{
		if (profile.isReadOnly())
		{
			return;
		}
		configManager.setConfiguration(CONFIG_GROUP, DATA_KEY_PREFIX + profile.name(), gson.toJson(profileOverrides.get(profile)));
	}

	/** Lowercases and strips colour tags so lookups are forgiving. */
	static String normalize(String rawName)
	{
		if (rawName == null)
		{
			return "";
		}
		return Text.removeTags(rawName).trim().toLowerCase(Locale.ROOT);
	}

	/** Strips colour tags but keeps the original casing, for display purposes. */
	static String cleanDisplayName(String rawName)
	{
		if (rawName == null)
		{
			return "";
		}
		return Text.removeTags(rawName).trim();
	}

	/** @param normalizedName a name already passed through {@link #normalize} */
	double getMultiplier(String normalizedName)
	{
		return profileOverrides.get(currentProfile).getOrDefault(normalizedName, 1.0);
	}

	/**
	 * Sets a track's multiplier in the active profile and persists it. A value of 1.0 clears the
	 * override instead of storing it, so untouched tracks don't bloat the saved config.
	 *
	 * @param displayName the track's un-normalized name, as shown in the panel
	 */
	void setMultiplier(String displayName, double value)
	{
		if (currentProfile.isReadOnly())
		{
			return;
		}
		value = clamp(value);
		String norm = normalize(displayName);
		Map<String, Double> map = profileOverrides.get(currentProfile);
		if (Math.abs(value - 1.0) < 0.001)
		{
			map.remove(norm);
		}
		else
		{
			map.put(norm, value);
		}
		persist(currentProfile);
	}

	static double clamp(double value)
	{
		value = Math.max(MIN_MULTIPLIER, Math.min(MAX_MULTIPLIER, value));
		// snap to the nearest 0.01 to avoid float drift
		return Math.round(value * 100.0) / 100.0;
	}

	/** Every known track, alphabetical, in its original display casing. A snapshot copy. */
	synchronized List<String> getAllTrackNames()
	{
		return new ArrayList<>(allTrackNames);
	}

	Profile getCurrentProfile()
	{
		return currentProfile;
	}

	/** Switches the active profile. Does not touch any stored data. */
	void setCurrentProfile(Profile profile)
	{
		currentProfile = profile == null ? Profile.USER_1 : profile;
		configManager.setConfiguration(CONFIG_GROUP, PROFILE_KEY, currentProfile.name());
	}

	/** Clears every override in the given profile back to 1.0 (no stored entries). No-op if read-only. */
	void resetProfile(Profile profile)
	{
		if (profile.isReadOnly())
		{
			return;
		}
		profileOverrides.put(profile, new HashMap<>());
		persist(profile);
	}

	/**
	 * Replaces every adjustment in {@code to} with a copy of those in {@code from}, so the copy can
	 * be edited freely without touching the source (e.g. the read-only Suggested Settings).
	 *
	 * @return false if nothing was copied (the target is read-only, or source and target are the same)
	 */
	boolean copyProfile(Profile from, Profile to)
	{
		if (to.isReadOnly() || from == to)
		{
			return false;
		}
		profileOverrides.put(to, new HashMap<>(profileOverrides.get(from)));
		persist(to);
		return true;
	}
}

